import{_ as n,c as a,o as t,aN as e}from"./chunks/framework.DUf1V_IZ.js";const u=JSON.parse('{"title":"TCP","description":"","frontmatter":{"date":"2026-08-05T16:00:00.000Z","title":"TCP","permalink":"/pages/3b4c5d","categories":["Protocol","传输层协议"]},"headers":[],"relativePath":"Protocol/02.传输层协议/02.tcp.md","filePath":"Protocol/02.传输层协议/02.tcp.md","lastUpdated":1785924051000}'),r={name:"Protocol/02.传输层协议/02.tcp.md"};function l(p,s,i,d,o,c){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="tcp-协议" tabindex="-1">TCP 协议 <a class="header-anchor" href="#tcp-协议" aria-label="Permalink to &quot;TCP 协议&quot;">​</a></h1><p>TCP（Transmission Control Protocol，<strong>传输控制协议</strong>）是 TCP/IP 协议族中传输层的两个核心协议之一，与 UDP 并列。它在 IP 协议（网络层）之上提供<strong>面向连接、可靠、字节流</strong>的传输服务，是Web、邮件、文件传输等绝大多数应用的底座。</p><blockquote><p>一句话：<strong>UDP 提供传输能力，TCP 提供传输保证。</strong> TCP 通过一整套机制把「不可靠的 IP 网络」包装成「对应用层可靠的字节流」。</p></blockquote><hr><h2 id="一、tcp-的核心特征" tabindex="-1">一、TCP 的核心特征 <a class="header-anchor" href="#一、tcp-的核心特征" aria-label="Permalink to &quot;一、TCP 的核心特征&quot;">​</a></h2><ul><li><strong>面向连接</strong>：通信前必须「三次握手」建立连接，结束后「四次挥手」释放。</li><li><strong>可靠交付</strong>：通过<strong>序号、确认（ACK）、超时重传、校验和</strong>保证数据不丢、不重、按序到达。</li><li><strong>字节流</strong>：没有消息边界，发送方多次写、接收方可能一次读（或反之）——存在「粘包/拆包」，需要应用层自己定界。</li><li><strong>流量控制</strong>：通过<strong>滑动窗口</strong>让发送方不超过接收方的处理能力。</li><li><strong>拥塞控制</strong>：通过慢启动、拥塞避免、快重传、快恢复等算法，在网络拥塞时主动减速，避免雪崩。</li><li><strong>全双工</strong>：连接建立后，双方可同时收发。</li></ul><hr><h2 id="二、tcp-报文格式" tabindex="-1">二、TCP 报文格式 <a class="header-anchor" href="#二、tcp-报文格式" aria-label="Permalink to &quot;二、TCP 报文格式&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|         源端口          |         目的端口          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                       序号 seq                          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                       确认号 ack                        |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>| 数据偏移 | 保留 |U|A|P|R|S|F|       窗口大小            |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|        校验和           |        紧急指针           |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                    选项（可选，如 MSS、窗口扩大）          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                          数据 ...                        |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>源/目的端口</td><td>标识两端进程，各 16 位</td></tr><tr><td>序号 seq</td><td>本报文段首个字节在数据流中的位置</td></tr><tr><td>确认号 ack</td><td>期望收到的<strong>下一个</strong>字节的序号（累计确认）</td></tr><tr><td>数据偏移</td><td>首部长度（以 4 字节为单位，含选项）</td></tr><tr><td>标志位</td><td>URG/ACK/PSH/RST/SYN/FIN，控制连接状态</td></tr><tr><td>窗口</td><td>接收方当前可接收的字节数（流量控制）</td></tr><tr><td>校验和</td><td>覆盖首部+数据+伪首部</td></tr><tr><td>紧急指针</td><td>URG=1 时有效，指出紧急数据末尾</td></tr></tbody></table><p>常用标志位：</p><ul><li><strong>SYN</strong>：同步序号，用于建立连接（三次握手）。</li><li><strong>ACK</strong>：确认有效。</li><li><strong>FIN</strong>：释放连接（四次挥手）。</li><li><strong>RST</strong>：复位，异常中断连接。</li><li><strong>PSH / URG</strong>：尽快交付 / 紧急数据。</li></ul><hr><h2 id="三、三次握手-建立连接" tabindex="-1">三、三次握手（建立连接） <a class="header-anchor" href="#三、三次握手-建立连接" aria-label="Permalink to &quot;三、三次握手（建立连接）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                                  服务端</span></span>
<span class="line"><span>  |                                      |</span></span>
<span class="line"><span>  | ---- SYN, seq=x ------------------&gt;  |   ① 服务端进入 LISTEN</span></span>
<span class="line"><span>  |                                      |</span></span>
<span class="line"><span>  | &lt;--- SYN+ACK, seq=y, ack=x+1 -----   |   ② 服务端进入 SYN_RCVD</span></span>
<span class="line"><span>  |                                      |</span></span>
<span class="line"><span>  | ---- ACK, seq=x+1, ack=y+1 -------&gt;  |   ③ 双方进入 ESTABLISHED</span></span>
<span class="line"><span>  |                                      |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>目的：双方确认<strong>彼此的收发能力</strong>都正常，并同步初始序号。防止已失效的连接请求突然又传到服务端造成误建。</p><hr><h2 id="四、四次挥手-释放连接" tabindex="-1">四、四次挥手（释放连接） <a class="header-anchor" href="#四、四次挥手-释放连接" aria-label="Permalink to &quot;四、四次挥手（释放连接）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                                  服务端</span></span>
<span class="line"><span>  |                                      |</span></span>
<span class="line"><span>  | ---- FIN, seq=u ------------------&gt;  |   ① 客户端 FIN_WAIT_1</span></span>
<span class="line"><span>  | &lt;--- ACK, ack=u+1 ----------------   |   ② 服务端 CLOSE_WAIT（仍可发数据）</span></span>
<span class="line"><span>  |                                      |</span></span>
<span class="line"><span>  | &lt;--- FIN, seq=v -------------------  |   ③ 服务端发完数据后 LAST_ACK</span></span>
<span class="line"><span>  | ---- ACK, ack=v+1 ---------------&gt;   |   ④ 客户端 TIME_WAIT → 2MSL 后 CLOSE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>为什么挥手是四次而不是三次？</strong> 因为 TCP 全双工，关闭时<strong>每个方向都要单独关闭</strong>：被动方收到 FIN 后先回 ACK（确认收到），但可能还有数据要发，等自己也没数据了再发 FIN。所以 ACK 和 FIN 被拆成了两个报文。</p><blockquote><p><strong>TIME_WAIT 与 2MSL</strong>：主动关闭方最后会进入 TIME_WAIT 并等待 2MSL（最长报文段寿命），确保最后的 ACK 能到达、且旧连接的残留报文在网络中消失，避免影响新连接。</p></blockquote><hr><h2 id="五、可靠性机制" tabindex="-1">五、可靠性机制 <a class="header-anchor" href="#五、可靠性机制" aria-label="Permalink to &quot;五、可靠性机制&quot;">​</a></h2><ul><li><strong>序号 + 确认</strong>：接收方用 ack 告知「已正确收到到哪」，发送方据此判断哪些需要重传。</li><li><strong>超时重传（RTO）</strong>：报文超时未收到 ACK 即重发；RTO 随网络状况动态估算。</li><li><strong>滑动窗口</strong>：接收方通过 <code>窗口</code> 字段告诉发送方「我还能收多少」，实现流量控制。</li><li><strong>拥塞控制</strong>：<code>慢启动 → 拥塞避免 → 快重传/快恢复</code>，根据丢包/延迟推测网络容量，避免把网络打满。</li></ul><hr><h2 id="六、与-udp-对比" tabindex="-1">六、与 UDP 对比 <a class="header-anchor" href="#六、与-udp-对比" aria-label="Permalink to &quot;六、与 UDP 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接性</td><td>面向连接（三次握手、四次挥手）</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠（确认、重传、序号）</td><td>不可靠（尽最大努力交付）</td></tr><tr><td>顺序性</td><td>保证按序到达</td><td>不保证顺序</td></tr><tr><td>数据边界</td><td>字节流，无消息边界（可能粘包/拆包）</td><td>保留报文边界（面向报文）</td></tr><tr><td>速度</td><td>较慢（握手、确认、控制开销）</td><td>较快</td></tr><tr><td>首部开销</td><td>20~60 字节</td><td>8 字节</td></tr><tr><td>流量/拥塞控制</td><td>有</td><td>无</td></tr><tr><td>通信模式</td><td>仅一对一</td><td>一对一、一对多、广播/组播</td></tr><tr><td>适用场景</td><td>文件传输、网页、邮件、SSH</td><td>音视频、DNS、游戏、实时通信</td></tr></tbody></table><hr><h2 id="七、典型应用" tabindex="-1">七、典型应用 <a class="header-anchor" href="#七、典型应用" aria-label="Permalink to &quot;七、典型应用&quot;">​</a></h2><ul><li><strong>HTTP / HTTPS</strong>：网页传输（HTTP/3 例外，底层是 QUIC over UDP）。</li><li><strong>FTP / SMTP / POP3</strong>：文件传输、邮件。</li><li><strong>SSH / Telnet</strong>：远程登录。</li><li><strong>数据库连接</strong>、<strong>消息队列</strong>等长连接、强可靠场景。</li></ul><hr><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><p><strong>Q1：TCP 会粘包吗？怎么解决？</strong> 会。TCP 是字节流，不存在消息边界，发送端多次 <code>write</code> 可能被合并、一次 <code>read</code> 可能拿到多段。解决办法（应用层定界）：固定长度、长度前缀、分隔符、或每次一发一收（短连接/请求-响应模型）。</p><p><strong>Q2：为什么 TIME_WAIT 要等 2MSL？</strong> 确保最后的 ACK 能到达被动方；同时让本连接产生的所有报文在网络中消亡，避免被后续同源同端口的新连接误收。</p><p><strong>Q3：TCP 和 UDP 怎么选？</strong> 对可靠性、顺序敏感（文件、网页、交易）→ TCP；对延迟敏感、可容忍丢包、需要广播/组播（音视频、游戏、DNS）→ UDP；也可像 QUIC 那样在 UDP 上自建可靠。</p>`,35)])])}const h=n(r,[["render",l]]);export{u as __pageData,h as default};
